<?php
namespace App\Http\Controllers;
use App\Models\Invoice; use App\Models\Client; use Illuminate\Http\Request; use Illuminate\View\View; use Illuminate\Http\RedirectResponse;
class InvoiceController extends Controller {
public function index():View{return view('invoices.index',['invoices'=>Invoice::with('client')->latest()->paginate(12)]);} public function create():View{return view('invoices.form',['clients'=>Client::orderBy('name')->get()]);}
public function store(Request $r):RedirectResponse{$data=$r->validate(['number'=>'required|string|max:40|unique:invoices,number','client_id'=>'required|exists:clients,id','issue_date'=>'required|date','due_date'=>'nullable|date|after_or_equal:issue_date','amount'=>'required|numeric|min:0','currency'=>'required|string|size:3','status'=>'required|in:draft,sent,paid,overdue']);$invoice=Invoice::create($data);return redirect()->route('invoices.show',$invoice)->with('success','Invoice created.');}
public function show(Invoice $invoice):View{return view('invoices.show',['invoice'=>$invoice->load('client')]);} public function edit(Invoice $invoice):View{return view('invoices.form',['invoice'=>$invoice,'clients'=>Client::orderBy('name')->get()]);}
public function update(Request $r,Invoice $invoice):RedirectResponse{$data=$r->validate(['number'=>'sometimes|required|string|max:40|unique:invoices,number,'.$invoice->id,'client_id'=>'sometimes|required|exists:clients,id','issue_date'=>'sometimes|required|date','due_date'=>'nullable|date|after_or_equal:issue_date','amount'=>'sometimes|required|numeric|min:0','currency'=>'sometimes|required|string|size:3','status'=>'sometimes|required|in:draft,sent,paid,overdue']);$invoice->update($data);return redirect()->route('invoices.show',$invoice)->with('success','Invoice updated.');} public function destroy(Invoice $invoice):RedirectResponse{$invoice->delete();return redirect()->route('invoices.index')->with('success','Invoice deleted.');}}
